//! Sequential exchange rendezvous.
//!
//! The exchange matches StarRocks' receiver-first dispatch with the senders that arrive later.
//! A same-node sender's rows stay on the GPU, parked in the engine as native batches; a remote
//! sender's batches arrive as staged packed bytes in this CN's arena (nixl tier, PLAN-PATH-B B5).
//! Either way, what is tracked here is which senders have finished and where their output sits.

use std::collections::HashMap;
use std::sync::Mutex;

use starrocks_thrift::internal_service::TExecPlanFragmentParams;
use tracing::info;

use crate::fragment_executor::{SenderSlot, StagedBatch};
use crate::result_store::FragmentInstanceId;

/// Receiver identity used by both the stream sink and exchange node.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub(crate) struct ExchangeKey {
    pub(crate) fragment_instance_id: FragmentInstanceId,
    pub(crate) node_id: i32,
}

/// One sender's output, and where it sits.
#[derive(Clone, Debug)]
pub(crate) enum SenderSource {
    /// A same-node sender whose batches the engine parked on the GPU.
    LocalParked {
        /// Sender output names, which become the input stream's column names.
        names: Vec<String>,
        /// Where the engine parked this sender's batches.
        slot: SenderSlot,
    },
    /// A remote sender whose packed batches were nixl-WRITTEN into this CN's staging arena and
    /// announced over `transmit_packed`. Counts toward readiness only once `closed`.
    Remote {
        /// Sender output names carried on every `transmit_packed` frame (first frame wins,
        /// later frames must match).
        names: Vec<String>,
        /// Sender ordinal, needed to `close_input` the engine stream it feeds.
        sender_id: i32,
        /// Batches staged in arrival (sequence) order; the engine releases each lease after
        /// pushing it.
        batches: Vec<StagedBatch>,
        /// The sender announced eos; no more frames may follow.
        closed: bool,
    },
}

impl SenderSource {
    /// The sender's output column names, whichever side of the wire it sits on.
    pub(crate) fn names(&self) -> &[String] {
        match self {
            Self::LocalParked { names, .. } | Self::Remote { names, .. } => names,
        }
    }

    /// Whether this sender has finished producing (a parked local sender always has).
    fn is_complete(&self) -> bool {
        match self {
            Self::LocalParked { .. } => true,
            Self::Remote { closed, .. } => *closed,
        }
    }
}

/// One exchange input of a receiver fragment whose sender set is complete.
#[derive(Debug)]
pub(crate) struct ReadyExchangeInput {
    pub(crate) node_id: i32,
    pub(crate) sources: Vec<SenderSource>,
}

/// A receiver fragment whose exchange inputs are all ready for sequential execution.
#[derive(Debug)]
pub(crate) struct ReadyFragment {
    pub(crate) params: TExecPlanFragmentParams,
    pub(crate) inputs: Vec<ReadyExchangeInput>,
}

#[derive(Debug)]
struct PendingReceiver {
    params: TExecPlanFragmentParams,
    expected_senders: HashMap<i32, usize>,
}

#[derive(Debug, Default)]
struct ExchangeState {
    receivers: HashMap<FragmentInstanceId, PendingReceiver>,
    sources: HashMap<ExchangeKey, HashMap<i32, SenderSource>>,
    /// Next expected `transmit_packed` sequence number per remote sender: a duplicate (below) is
    /// dropped idempotently — brpc reconnect-retry can replay a frame — and a gap (above) is a
    /// lost frame, which must fail the query rather than silently drop rows.
    remote_seq: HashMap<(ExchangeKey, i32), i64>,
}

/// Matches receiver-first StarRocks dispatch with later same-node sender results.
#[derive(Debug, Default)]
pub(crate) struct LocalExchange {
    inner: Mutex<ExchangeState>,
----
    inner: Mutex<ExchangeState>,
}

impl LocalExchange {
    /// Registers a receiver fragment, returning it when every exchange input is complete.
    pub(crate) fn register_receiver(
        &self,
        fragment_instance_id: FragmentInstanceId,
        expected_senders: Vec<(i32, usize)>,
        params: TExecPlanFragmentParams,
    ) -> Result<Option<ReadyFragment>, String> {
        if expected_senders.is_empty() {
            return Err("receiver fragment has no exchange inputs".to_string());
        }
        let mut expected_by_node = HashMap::with_capacity(expected_senders.len());
        for (node_id, expected) in expected_senders {
            if expected == 0 {
                return Err(format!("exchange node {node_id} expects no senders"));
            }
            if expected_by_node.insert(node_id, expected).is_some() {
                return Err(format!(
                    "duplicate exchange node {node_id} in receiver fragment"
                ));
            }
        }
        let mut state = self.lock();
        if state.receivers.contains_key(&fragment_instance_id) {
            return Err(format!(
                "duplicate receiver registration for fragment {fragment_instance_id}"
            ));
        }
        state.receivers.insert(
            fragment_instance_id,
            PendingReceiver {
                params,
                expected_senders: expected_by_node,
            },
        );
        Self::take_ready(&mut state, fragment_instance_id)
    }

    /// Records one sender as produced, returning the receiver when this completes its sender set.
    pub(crate) fn push_sender(
        &self,
        key: ExchangeKey,
        sender_id: i32,
        source: SenderSource,
    ) -> Result<Option<ReadyFragment>, String> {
        let mut state = self.lock();
        let senders = state.sources.entry(key).or_default();
        if senders.contains_key(&sender_id) {
            return Err(format!("duplicate sender {sender_id} for exchange {key:?}"));
        }
        senders.insert(sender_id, source);
        Self::take_ready(&mut state, key.fragment_instance_id)
    }

    /// Records one `transmit_packed` frame from a remote sender: a staged batch, eos, or both.
    /// Returns the receiver when the eos completes its sender set.
    pub(crate) fn push_remote_frame(
        &self,
        key: ExchangeKey,
        sender_id: i32,
        seq: i64,
        eos: bool,
        names: Vec<String>,
        batch: Option<StagedBatch>,
    ) -> Result<Option<ReadyFragment>, String> {
        if names.is_empty() {
            return Err(format!(
                "remote sender {sender_id} for exchange {key:?} sent a frame without column \
                 names; the receiver cannot bind its input stream schema"
            ));
        }
        if batch.is_none() && !eos {
            return Err(format!(
                "remote sender {sender_id} for exchange {key:?} sent frame seq {seq} carrying \
                 neither a batch nor eos"
            ));
        }
        let mut state = self.lock();

        let expected_seq = state.remote_seq.entry((key, sender_id)).or_insert(0);
        if seq < *expected_seq {
            // brpc reconnect-retry can replay a frame the peer already processed; its batch (if
            // any) landed in the same lease the first delivery recorded, so dropping the replay
            // loses nothing and leaks nothing.
            info!(
                exchange = ?key,
                sender_id, seq, "dropping duplicate remote exchange frame"
            );
            return Ok(None);
        }
        if seq > *expected_seq {
            return Err(format!(
                "remote sender {sender_id} for exchange {key:?} skipped from frame seq \
                 {expected_seq} to {seq}; a frame was lost"
            ));
        }
        *expected_seq += 1;

        let senders = state.sources.entry(key).or_default();
        let source = senders
            .entry(sender_id)
            .or_insert_with(|| SenderSource::Remote {
                names: names.clone(),
                sender_id,
                batches: Vec::new(),
                closed: false,
            });
        let SenderSource::Remote {
            names: known_names,
            batches,
            closed,
            ..
        } = source
        else {
            return Err(format!(
                "remote frame for exchange {key:?} sender {sender_id} collides with a local \
                 parked sender of the same id"
            ));
        };
        if *closed {
            return Err(format!(
                "remote sender {sender_id} for exchange {key:?} sent frame seq {seq} after eos"
            ));
        }
        if known_names != &names {
            return Err(format!(
                "remote sender {sender_id} for exchange {key:?} changed its column names from \
                 {known_names:?} to {names:?}"
            ));
        }
        if let Some(batch) = batch {
            if batch.metadata.is_empty() {
                return Err(format!(
                    "remote sender {sender_id} for exchange {key:?} sent frame seq {seq} with \
                     empty pack metadata"
                ));
            }
            batches.push(batch);
        }
        if eos {
            *closed = true;
        }
        Self::take_ready(&mut state, key.fragment_instance_id)
    }

    fn take_ready(
        state: &mut ExchangeState,
        fragment_instance_id: FragmentInstanceId,
    ) -> Result<Option<ReadyFragment>, String> {
        let Some(receiver) = state.receivers.get(&fragment_instance_id) else {
            return Ok(None);
        };
        for (&node_id, &expected) in &receiver.expected_senders {
            let key = ExchangeKey {
                fragment_instance_id,
                node_id,
            };
            let sources = state.sources.get(&key);
            let total = sources.map(HashMap::len).unwrap_or(0);
            if total > expected {
                return Err(format!(
                    "exchange {key:?} received {total} senders but expected {expected}"
                ));
            }
            // A remote sender counts only once its eos arrived; a local parked one is done by
            // construction.
            let complete = sources
                .map(|senders| {
                    senders
                        .values()
                        .filter(|source| source.is_complete())
                        .count()
                })
                .unwrap_or(0);
            if complete != expected {
                return Ok(None);
            }
        }

        let receiver = state
            .receivers
            .remove(&fragment_instance_id)
            .expect("receiver checked above");
        let mut node_ids = receiver.expected_senders.into_keys().collect::<Vec<_>>();
        node_ids.sort_unstable();
        let inputs = node_ids
            .into_iter()
            .map(|node_id| {
                let key = ExchangeKey {
                    fragment_instance_id,
                    node_id,
                };
                let mut senders = state.sources.remove(&key).unwrap_or_default();
                let mut sender_ids = senders.keys().copied().collect::<Vec<_>>();
                sender_ids.sort_unstable();
                let sources = sender_ids
                    .into_iter()
                    .map(|sender_id| senders.remove(&sender_id).expect("sender id came from map"))
                    .collect();
                ReadyExchangeInput { node_id, sources }
            })
            .collect();
        // The receiver is leaving the rendezvous; drop its remote-sender sequence tracking too.
        state
            .remote_seq
            .retain(|(key, _), _| key.fragment_instance_id != fragment_instance_id);
        Ok(Some(ReadyFragment {
            params: receiver.params,
            inputs,
        }))
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, ExchangeState> {
        self.inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }
}

    /// Reads `SIRIUS_CN_ASYNC_SENDER_DISPATCH` once at bring-up: `1`, `true` or `on` queue
    /// sender-only fragments (no exchange input, no RESULT_SINK) on the dispatch worker instead of
    /// running them inside their exec_plan_fragment RPC. Off by default.
    ///
    /// Why it exists: the FE deploys the first fragment instance of every node in one wave and
    /// waits for all of those RPCs before it deploys the remaining instances. A sender that runs
    /// inside its RPC holds that wave open for its whole scan, so on a gather (q06: partial ->
    /// EXCHANGE UNPARTITIONED) the node that also hosts the merge fragment only receives its own
    /// scan after every other node's scan has finished. Measured on 4 GB200 CNs at SF1000: three
    /// scans started together and the fourth 726 ms later, right after the last `transmitted
    /// batches via nixl`. Returning as soon as the fragment is queued lets every scan start in the
    /// same wave.
    ///
    /// Why it is off by default: a queued sender's failure (a malformed sink, an untranslatable
    /// plan, a failed remote drain) is attributed through `results.fail_query`, which only reaches
    /// result instances reserved on this node. When the result fragment lives on another node the
    /// FE learns of the failure through its query timeout instead of this RPC's status. Flip the
    /// default once a sender failure is forwarded to the receiver's node.
    fn async_sender_dispatch_from_env() -> bool {
        matches!(
            std::env::var("SIRIUS_CN_ASYNC_SENDER_DISPATCH").as_deref(),
            Ok("1") | Ok("true") | Ok("TRUE") | Ok("on") | Ok("ON")
        )
    }

    /// Overrides the bring-up setting; tests use it to exercise the queued path without touching
    /// the process environment.
    #[cfg(test)]
    pub(crate) fn set_async_sender_dispatch(&self, enabled: bool) {
        self.core
            .async_sender_dispatch
            .store(enabled, std::sync::atomic::Ordering::Relaxed);
    }

    /// Queues a sender-only fragment on the dispatch worker. Returns `Ok(false)` when the
    /// fragment must take the inline path (exchange receiver, RESULT_SINK root, survey mode, or
    /// the switch is off); descriptor tables are resolved at arrival either way, so the FE's
    /// per-query descriptor cache protocol sees the same order as before.
    fn try_dispatch_sender(
        &self,
        params: &TExecPlanFragmentParams,
    ) -> std::result::Result<bool, String> {
        if !self
            .core
            .async_sender_dispatch
            .load(std::sync::atomic::Ordering::Relaxed)
            || std::env::var_os("SIRIUS_CN_TRANSLATE_ONLY").is_some()
            || !ServiceCore::receiver_exchanges(params)?.is_empty()
            || ServiceCore::is_mysql_result_sink(params)?
        {
            return Ok(false);
        }
        let params = self.core.resolve_descriptor_table(params)?;
        self.dispatch(ReadyFragment {
            params,
            inputs: Vec::new(),
        })?;
        Ok(true)
    }

    /// Hands a ready receiver to the dispatch worker so this RPC thread returns immediately
    /// instead of blocking on the receiver's whole execution.
    fn dispatch(&self, ready: ReadyFragment) -> std::result::Result<(), String> {
        self.ready_fragments.send(ready).map_err(|_| {
            "fragment dispatch worker has exited; cannot execute receiver fragment".to_string()
----
    /// once each destination's copy is actually across the wire.
    ///
    /// A receiver dispatched here can now run concurrently with its own query's drains. That
    /// costs nothing in correctness (its sender set was already complete, so it reads no data
    /// the drains produce) but it does mean the parked batches of the not-yet-drained
    /// destinations stay resident while it computes — the deliberate memory-for-latency trade.
    fn dispatch_then_join(&self, outcome: FragmentOutcome) -> std::result::Result<(), String> {
        let mut dispatch_error = None;
        for ready in outcome.ready {
            if let Err(err) = self.dispatch(ready) {
                dispatch_error.get_or_insert(err);
            }
        }
        // Joined unconditionally, even when dispatch failed: the drains are already in flight.
        let drain_result = outcome.drains.join();
        match (drain_result, dispatch_error) {
            (Ok(()), None) => Ok(()),
            (Ok(()), Some(dispatch)) => Err(dispatch),
            // A drain failure names the destination and the transport fault, so it is the more
            // useful cause to hand the FE; a dispatch failure only ever means "this CN is
            // shutting down". Report the drain error, keep the other in the log.
            (Err(drain), dispatch) => {
                if let Some(dispatch) = dispatch {
                    tracing::error!(error = %dispatch, "receiver dispatch also failed");
                }
                Err(drain)
            }
        }
    }
}

/// Executes ready receiver fragments sequentially, off the RPC threads.
///
/// Exits when every service clone has dropped its sender; the worker then releases its core
/// handle (and with it the executor), keeping engine teardown ordered.
fn dispatch_worker(core: Arc<ServiceCore>, inbox: mpsc::Receiver<ReadyFragment>) {
    while let Ok(ready) = inbox.recv() {
        // A receiver can itself be a sender whose completion readies further receivers (a
        // middle fragment, possibly fanning out); chase the whole set inline — this thread is
        // already off the RPC path.
        let mut queue = vec![ready];
        while let Some(ready) = queue.pop() {
            queue.extend(core.run_ready_fragment(ready));
        }
    }
}

impl PInternalService for SiriusComputeNodeService {
    /// Handles a single FE-dispatched plan fragment thrift attachment. A root fragment without an
    /// exchange executes immediately; an exchange receiver waits for its local sender fragments.
    /// The final rows are buffered for `fetch_data`.
----
            status: Some(status),
        }
        .into())
    }

    /// Best-effort cancellation stub: acknowledges the FE with OK so its shared jprotobuf
    /// channel stays healthy — the default unrouted reply is a PRPC-level error frame, and the
    /// FE reaps the timed-out future in a way that misattributes later replies on the channel.
    /// A still-waiting result entry is failed so a `fetch_data` long-poll returns immediately.
    /// Real teardown (aborting the engine run, freeing GPU buffers, dropping parked exchange
    /// state) is a separate work item.
    #[instrument(skip_all)]
    async fn cancel_plan_fragment(
        &self,
        request: PCancelPlanFragmentRequest,
        _attachment: Vec<u8>,
    ) -> Result<crate::prpc::Reply<PCancelPlanFragmentResult>, crate::prpc::Error> {
        let id = FragmentInstanceId::from(&request.finst_id);
        info!(
            fragment_instance_id = %id,
            query_id = ?request.query_id.as_ref().map(FragmentInstanceId::from),
            cancel_reason = request.cancel_reason,
            error_message = ?request.error_message,
            "acknowledging cancel_plan_fragment (best-effort: no engine-side abort yet)"
        );
        let mut reason = format!("fragment instance {id} was cancelled by the FE");
        if let Some(message) = request.error_message.as_ref().filter(|msg| !msg.is_empty()) {
            reason = format!("{reason}: {message}");
        }
        self.core.results.cancel(id, reason);
        Ok(PCancelPlanFragmentResult {
            status: Self::ok_status(),
        }
        .into())
    }

}

impl SiriusComputeNodeService {
    /// Deserializes one binary-thrift TExecPlanFragmentParams attachment and processes it,
    /// handing any completed receiver to the dispatch worker.
    fn exec_single_attachment(
        &self,
        protocol: Option<&str>,
        attachment: &[u8],
    ) -> std::result::Result<(), String> {
        Self::ensure_binary_protocol(protocol)?;
        let params = Self::deserialize_binary::<TExecPlanFragmentParams>(attachment)
            .map_err(|err| format!("failed to deserialize TExecPlanFragmentParams: {err}"))?;
        if self.try_dispatch_sender(&params)? {
            return Ok(());
        }
        self.dispatch_then_join(self.core.process_fragment(&params)?)
    }

    /// Records one remote exchange frame in the rendezvous (or releases a canary lease), handing
    /// a completed receiver to the dispatch worker.
----
    }

    /// Runs one dispatched receiver, parking a failure where `fetch_data` can see it. Returns
    /// the next receiver when this fragment's own sink completed another sender set.
    fn run_ready_fragment(&self, ready: ReadyFragment) -> Vec<ReadyFragment> {
        let id = Self::fragment_instance_id(&ready.params);
        let query_id = Self::query_id(&ready.params);
        let is_result_fragment = matches!(Self::is_mysql_result_sink(&ready.params), Ok(true));
        // `join_into_ready` keeps this fragment's own remote drains inside this call, so a drain
        // failure is attributed to the same query as any other failure of this fragment.
        match self
            .execute_ready_fragment(ready)
            .and_then(FragmentOutcome::join_into_ready)
        {
            Ok(next) => next,
            Err(error) => {
                match (id, query_id) {
                    (Some(id), Some(query_id)) => {
                        if is_result_fragment {
                            // The FE polls fetch_data on this id; its reserved entry becomes
                            // the error instead of waiting forever.
                            tracing::error!(fragment_instance_id = %id, error = %error, "dispatched result fragment failed");
                        } else {
                            // An intermediate receiver has no FE-polled entry of its own, so
                            // its failure must reach the query's result-fragment instances —
                            // otherwise the FE polls until its timeout and the stalled
                            // fetch_data wedges this CN's whole frame loop.
                            tracing::error!(
                                fragment_instance_id = %id,
                                error = %error,
                                "dispatched intermediate receiver fragment failed; failing the query's result fragments"
                            );
                        }
                        // Fails this id, every reserved result instance of the query, and
                        // records the failure so a result fragment arriving later fails on
                        // registration instead of waiting on senders that never deliver.
                        self.results.fail_query(query_id, id, error);
                    }
                    (Some(id), None) => {
                        // Defensive: exec params carry both ids or neither, so this arm should
                        // be unreachable. Park the error under the instance id at least.
                        tracing::error!(fragment_instance_id = %id, error = %error, "dispatched receiver fragment without a query_id failed");
                        self.results.fail(id, error);
                    }
                    (None, _) => {
                        tracing::error!(error = %error, "dispatched receiver fragment without a fragment_instance_id failed");
                    }
                }
                Vec::new()
            }
        }
    }

    /// Processes one fragment and buffers supported RESULT_SINK rows for later `fetch_data`.
    /// Shared by single and batch dispatch; exchange receivers are registered until their local
    /// sender output is materialized. Returns a receiver whose sender set this fragment
    /// completed — the caller decides where it executes (RPC handlers hand it to the dispatch
    /// worker; the worker itself runs it inline).
    fn process_fragment(
        &self,
        params: &TExecPlanFragmentParams,
    ) -> std::result::Result<FragmentOutcome, String> {
        let params = self.resolve_descriptor_table(params)?;
        let dump_seq = Self::dump_fragment(&params);
        // Survey mode: accept every fragment so the FE dispatches (and we dump) the whole
        // plan even when translation fails. Queries still fail at fetch_data.
        if std::env::var_os("SIRIUS_CN_TRANSLATE_ONLY").is_some() {
            if let Err(err) = self.translate_fragment_logged(&params, dump_seq) {
                tracing::warn!(error = %err, "translate-only mode: accepting untranslatable fragment");
            }
            return Ok(FragmentOutcome::default());
        }
        let expected_senders = Self::receiver_exchanges(&params)?;
        if !expected_senders.is_empty() {
            let fragment_instance_id = Self::fragment_instance_id(&params)
                .ok_or_else(|| "exchange receiver is missing a fragment_instance_id".to_string())?;
            if Self::is_mysql_result_sink(&params)? {
                let query_id = Self::query_id(&params)
                    .ok_or_else(|| "exchange receiver is missing a query_id".to_string())?;
                self.results.reserve(fragment_instance_id, query_id);
            }
            return Ok(FragmentOutcome::from_ready(
                self.exchanges
                    .register_receiver(fragment_instance_id, expected_senders, params)?
                    .into_iter()
                    .collect(),
            ));
        }

        let translated = self.translate_fragment_logged(&params, dump_seq)?;
        self.execute_fragment(&params, translated)
    }

    /// Restores descriptor tables omitted by StarRocks's per-query descriptor cache protocol.
    fn resolve_descriptor_table(
        &self,
        params: &TExecPlanFragmentParams,
    ) -> std::result::Result<TExecPlanFragmentParams, String> {
        let mut resolved = params.clone();
        let Some(query_id) = params
            .params
            .as_ref()
            .map(|exec| FragmentInstanceId::from(&exec.query_id))
        else {
            return Ok(resolved);
        };
        let Some(desc) = params.desc_tbl.as_ref() else {
            return Ok(resolved);
        };
        let is_cached_reference = desc.is_cached == Some(true)
            && desc.slot_descriptors.as_ref().is_none_or(Vec::is_empty)
            && desc.tuple_descriptors.is_empty()
            && desc.table_descriptors.as_ref().is_none_or(Vec::is_empty);
        let mut cache = self
            .descriptor_tables
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if is_cached_reference {
            resolved.desc_tbl = Some(
                cache
                    .get(&query_id)
                    .cloned()
                    .ok_or_else(|| format!("descriptor table cache miss for query {query_id}"))?,
            );
        } else {
            cache.insert(query_id, desc.clone());
        }
        Ok(resolved)
    }

    /// Writes the received fragment params to `$SIRIUS_CN_DUMP_FRAGMENTS/fragment-<seq>.txt`
    /// (debug format) for offline plan analysis. No-op when the variable is unset.
    fn dump_fragment(params: &TExecPlanFragmentParams) -> Option<u64> {
        use std::sync::atomic::{AtomicU64, Ordering};
        let Ok(dir) = std::env::var("SIRIUS_CN_DUMP_FRAGMENTS") else {
            return None;
        };
        static SEQ: AtomicU64 = AtomicU64::new(0);
        let seq = SEQ.fetch_add(1, Ordering::Relaxed);
        let path = std::path::Path::new(&dir).join(format!("fragment-{seq:04}.txt"));
        if let Err(err) = std::fs::write(&path, format!("{params:#?}")) {
            tracing::warn!(error = %err, path = %path.display(), "failed to dump fragment params");
        }
        Some(seq)
    }

    /// Executes a fragment that reads no exchange input.
    fn execute_fragment(
        &self,
        params: &TExecPlanFragmentParams,
        translated: TranslatedPlan,

fn execute_fragment_with_inputs(
    &self,
    params: &TExecPlanFragmentParams,
    translated: TranslatedPlan,
    inputs: Vec<(i32, Vec<SenderSlot>)>,
    remote_inputs: Vec<(i32, i32, Vec<StagedBatch>)>,
) -> std::result::Result<FragmentOutcome, String> {
    if Self::is_mysql_result_sink(params)? {
        let id = Self::fragment_instance_id(params).ok_or_else(|| {
            "RESULT_SINK fragment is missing a fragment_instance_id".to_string()
        })?;
        let result = self
            .run_labeled(
                "result",
                FragmentRun {
                    plan: &translated,
                    inputs: inputs.clone(),
                    remote_inputs,
                    outputs: Vec::new(),
                    broadcast: false,
                    hash_keys: Vec::new(),
                    label: Self::fragment_label(params),
                },
            )?
            .ok_or_else(|| "result fragment returned no rows".to_string())?;
        let batch = result_encoder::MysqlResultEncoder::encode(&result.batches, 0)?;
        self.results.insert(id, batch);
        return Ok(FragmentOutcome::default());
    }

    let Some(sink) = params
        .fragment
        .as_ref()
        .and_then(|fragment| fragment.output_sink.as_ref())
    else {
        // The FE attaches a sink to every fragment it dispatches (PlanFragment.toThrift),
        // so a sinkless fragment only reaches here from a translate-only fixture.
        tracing::warn!(
            fragment = %Self::fragment_context(params),
            "fragment carries no output sink; nothing consumes its output"
        );
        return Ok(FragmentOutcome::default());
    };
    // Accepting an unhandled sink discards the fragment's whole output: its consumers wait
    // forever, the FE's fetch_data long-poll times out, and its serial channel wedges
    // cluster-wide. Refuse by name so the FE error says which plan shape is unsupported.
    if sink.type_ != TDataSinkType::DATA_STREAM_SINK {
        return Err(format!(
            "{} carries a {} output sink, which this CN does not support",
            Self::fragment_context(params),
            Self::data_sink_type_name(sink.type_)
        ));
    }
    let stream_sink = sink.stream_sink.as_ref().ok_or_else(|| {
        format!(
            "{} carries a DATA_STREAM_SINK with no stream_sink payload",
            Self::fragment_context(params)
        )
    })?;
    if stream_sink.limit.is_some_and(|limit| limit >= 0) {
        return Err("data stream sink limits are not supported".to_string());
    }
    if let Some(columns) = stream_sink
        .output_columns
        .as_ref()
        .filter(|columns| !columns.is_empty())
        && columns
            .iter()
            .copied()
            .ne(0..translated.output_names.len() as i32)
    {
        return Err(
            "non-identity data stream sink output_columns are not supported".to_string(),
        );
    }
    let exec = params
        .params
        .as_ref()
        .ok_or_else(|| "DATA_STREAM_SINK fragment is missing execution params".to_string())?;
    let destinations = exec
        .destinations
        .as_ref()
        .filter(|destinations| !destinations.is_empty())
        .ok_or_else(|| "DATA_STREAM_SINK fragment has no destinations".to_string())?;
    let sender_id = exec.sender_id.unwrap_or(0);
    // Fan-out shape: one destination is a gather regardless of the partition label;
    // UNPARTITIONED with N destinations broadcasts the full output to every receiver
    // (each destination drains its own copy from its own output stream). Hash-partitioned
    // fan-out is the second half of #838 and still refuses.
    if destinations.len() > 1 {
        use starrocks_thrift::partitions::TPartitionType;
        match stream_sink.output_partition.type_ {
            TPartitionType::UNPARTITIONED => {}
            TPartitionType::HASH_PARTITIONED => {
                if translated.output_partition_columns.is_none() {
                    return Err(
                        "a hash-partitioned data stream sink translated without partition \
                         key columns"
                            .to_string(),
                    );
                }
            }
            other => {
                return Err(format!(
                    "a data stream sink with {} destinations carries partition type {:?}, \
                     which this CN does not support",
                    destinations.len(),
                    other
                ));
            }
        }
    }
    let hash_keys = if destinations.len() > 1 {
        translated
            .output_partition_columns
            .clone()
            .unwrap_or_default()
    } else {
        Vec::new()
    };
    let broadcast = destinations.len() > 1 && hash_keys.is_empty();

    // Route every destination BEFORE running: a remote destination without a transport (or
    // a duplicate) must fail before any GPU work happens. Destination i then drains the
    // sender's output stream i -- the FE's destination order, positionally.
    let mut slots: Vec<SenderSlot> = Vec::with_capacity(destinations.len());
    let mut routes = Vec::with_capacity(destinations.len());
    for destination in destinations {
        let slot = SenderSlot {
            fragment_instance_id: FragmentInstanceId::from(&destination.fragment_instance_id),
            node_id: stream_sink.dest_node_id,
            sender_id,
        };
        if slots.contains(&slot) {
            return Err(format!(
                "duplicate destination {slot:?} in one data stream sink; two claims would \
                 race over one output stream"
            ));
        }
        let route = self.route_destination(destination)?;
        if let DestinationRoute::Remote { host, brpc_port } = &route
            && self.transport.is_none()
        {
            return Err(format!(
                "cross-node exchange to {host}:{brpc_port} needs the nixl transport \
                 tier, which is not active: build the CN with the `nixl-transport` \
                 feature (default) and set SIRIUS_EXCHANGE_STAGING_BYTES so the \
                 exchange staging arena exists"
            ));
        }
        slots.push(slot);
        routes.push(route);
    }

    // The sender's rows stay on the GPU, parked once with one output stream per
    // destination; only rendezvous bookkeeping and packed exports leave the engine thread.
    self.run_labeled(
        "sender",
        FragmentRun {
            plan: &translated,
            inputs,
            remote_inputs,
            outputs: slots.clone(),
            broadcast,
            hash_keys,
            label: Self::fragment_label(params),
        },
    )?;

    // Local destinations first: their rendezvous is immediate bookkeeping and fails fast.
    let mut ready_receivers = Vec::new();
    for (slot, route) in slots.iter().zip(&routes) {
        if matches!(route, DestinationRoute::Local) {
            let ready = self.exchanges.push_sender(
                ExchangeKey {
                    fragment_instance_id: slot.fragment_instance_id,
                    node_id: slot.node_id,
                },
                sender_id,
                SenderSource::LocalParked {
                    names: translated.output_names.clone(),
                    slot: *slot,
                },
            )?;
            ready_receivers.extend(ready);
        }
    }
    // Remote destinations second: POST each drain and keep its ticket instead of blocking
    // here. The caller dispatches `ready_receivers` first and joins the tickets after, so a
    // local receiver whose sender set this push just completed starts while the transport
    // thread is still draining this CN's remote destinations — measured, that wait was
    // 3 x 30 ms per CN on q14 SF500's 948 MB/destination stage.
    //
    // ORDER IS UNCHANGED, and deliberately so: one FIFO request channel into ONE transport
    // thread that still handles `SendFragment` inline means the drains still run one at a
    // time, in the FE's destination order, with every frame of a destination issued by that
    // single thread. `seq`, eos, and the exactly-once `drop_parked` all stay inside the
    // transport thread's own drain loop, so the receiver's per-(exchange, sender) gap check
    // (local_exchange.rs:180-197) sees exactly the byte sequence it sees today.
    let mut drains = SenderDrains::default();
    for (slot, route) in slots.iter().zip(&routes) {
        if let DestinationRoute::Remote { host, brpc_port } = route {
            let transport = self.transport.as_ref().expect("routed before running");
            let spec = RemoteSendSpec {
                host: host.clone(),
                brpc_port: *brpc_port,
                slot: *slot,
                names: translated.output_names.clone(),
                label: Self::fragment_label(params),
            };
            match transport.start_fragment(spec) {
                Ok(ticket) => drains.push(ticket),
                // Posting failed (the transport is shutting down). Join what is already in
                // flight before unwinding: a ticket dropped un-joined discards a real drain
                // failure, and this is the one path where tickets exist and `?` could fire.
                Err(err) => {
                    let _ = drains.join();
                    return Err(err);
                }
            }
        }
    }
    Ok(FragmentOutcome {
        ready: ready_receivers,
        drains,
    })
}

