pub(crate) fn translate_plan(
    plan: &TPlan,
    root_output_exprs: &[TExpr],
    desc: &DescriptorTable,
    scan_paths: &ScanFilePaths,
    exchange_inputs: &std::collections::HashMap<i32, &ExchangeInput>,
    registry: &mut ExtensionRegistry,
